4826: # order - never a List: @() over a List property fails on Windows PowerShell 5.1);
4827: # Considered (entries walked); Error ('' or the refusal: none available / no entry for
4828: # $Model / the first entry's identity error under -SkipPreflight) }.
4829: function Select-RosterReviewer {
4830:     param($Roster, $Config, [object[]]$Consults, [string]$Launcher, [hashtable]$LoginCache = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [string]$Model = '', [switch]$SkipPreflight, [string]$Engine = '', [hashtable]$EngineLaunchers = $null, [switch]$NoNetwork)
