4832:     $r = [pscustomobject]@{ Entry = $null; Identity = $null; Verdict = $null; Skipped = [object[]]@(); Considered = 0; Error = '' }
4833:     $listing = New-Object System.Collections.Generic.List[string]
4834:     foreach ($e in @($Roster.Entries)) {
4835:         $entryEngine = if ($e.PSObject.Properties['Engine'] -and $e.Engine) { [string]$e.Engine } else { 'codex' }
4836:         if ($Engine -and $entryEngine -ne $Engine) { continue }
4837:         $entryLauncher = Get-EngineLauncher -Engine $entryEngine -Launchers $EngineLaunchers -CodexLauncher $Launcher
4838:         $id = Resolve-ReviewerIdentity -Config $Config -Provider $e.Provider -Model $e.Model -OpenAiBaseUrl $OpenAiBaseUrl -Engine $entryEngine -Launcher $entryLauncher
4839:         if ($Model -and $id.Model -cne $Model) { continue }
4840:         $r.Considered++
4841:         $block = Get-EngineLaunchBlock -Engine $entryEngine
4842:         if ($block) {
4843:             $skipped.Add([pscustomobject]@{ provider = $e.Provider; model = $id.Model; engine = $entryEngine; reason = "refused: $block" })
4844:             $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) (refused: $block)")
4845:             continue
4846:         }
4847:         if ($SkipPreflight) {
4848:             if ($id.Error) { $r.Error = $id.Error; return $r }
4849:             $r.Entry = $e; $r.Identity = $id
4850:             $r.Skipped = [object[]]$skipped.ToArray()
4851:             return $r
4852:         }
4853:         $health = $null
4854:         if ($id.Resolved) { $health = Get-EndpointHealth -Consults $Consults -Fingerprint $id.Fingerprint -UtcNow $UtcNow }
4855:         $verdict = Get-PreflightVerdict -Identity $id -Config $Config -Launcher $entryLauncher -Health $health -LoginCache $LoginCache -Anonymous:($e.Auth -eq 'none') -RosterWalk -NoNetwork:$NoNetwork
4856:         if ($verdict.State -eq 'available') {
