4912:             $reason = "weighty reviewer; purpose $purposeLabel is light (use -PanelAll)"
4913:         }
4914:         $members.Add([pscustomobject]@{ Entry = $e; Identity = $id; State = $state; Reason = $reason })
4915:         $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) ($(if ($state -eq 'run') { 'runs' } else { $reason }))")
