4931: # The concurrency plan of a panel (0.4.x wave 21, D8 - endpoint-aware): members that reach the
4932: # same ENDPOINT run one after another, members of different endpoints at once. An endpoint
4933: # group is the members of one provider label, merged with every other label whose members
4934: # resolve to the same provider fingerprint (two labels on one base URL; every agy label - they
4935: # share one Google sign-in). A group runs 1 member at a time unless the roster's top-level
4936: # "parallel" raises its label (a merged group: the smallest limit of its labels); -Cap
4937: # (-PanelConcurrency) caps the total (0 = no cap, 1 = strictly one after another in roster
4938: # order). $Runners: the members Select-PanelMembers runs (State 'run'), in roster order.
4939: # { Groups (object[] of { Labels (string[]); Limit; Positions (int[] roster positions) });
4940: #   GroupOf (hashtable roster position -> group index); Cap; Effective (the most members
4941: #   that can run at once); Text ('at once' | 'one after another' | 'at most <k> at a time');
4942: #   Limits (ordered: label -> its group's limit, roster order) }
4943: function Get-PanelPlan {
4944:     param([object[]]$Runners, [hashtable]$Parallel = $null, [int]$Cap = 0)
4945:     $labels = New-Object System.Collections.Generic.List[string]
4946:     $fps = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
4947:     foreach ($m in @($Runners | Where-Object { $_ })) {
4948:         $label = [string]$m.Entry.Provider
4949:         if (-not $fps.ContainsKey($label)) { $fps[$label] = New-Object System.Collections.Generic.List[string]; $labels.Add($label) }
4950:         $fp = ''
4951:         if ($m.Identity -and $m.Identity.Resolved) { $fp = [string]$m.Identity.Fingerprint }
4952:         if ($fp -and -not $fps[$label].Contains($fp)) { $fps[$label].Add($fp) }
4953:     }
4954:     # one group per label, then labels that share a fingerprint are merged (to a fixed point)
4955:     $groupOfLabel = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
4956:     for ($i = 0; $i -lt $labels.Count; $i++) { $groupOfLabel[$labels[$i]] = $i }
4957:     $changed = $true
4958:     while ($changed) {
4959:         $changed = $false
4960:         for ($i = 0; $i -lt $labels.Count; $i++) {
4961:             for ($j = $i + 1; $j -lt $labels.Count; $j++) {
4962:                 $gi = $groupOfLabel[$labels[$i]]; $gj = $groupOfLabel[$labels[$j]]
4963:                 if ($gi -eq $gj) { continue }
4964:                 $shared = @($fps[$labels[$i]] | Where-Object { $fps[$labels[$j]].Contains($_) }).Count -gt 0
4965:                 if (-not $shared) { continue }
4966:                 $keep = [Math]::Min($gi, $gj); $drop = [Math]::Max($gi, $gj)
4967:                 foreach ($l in $labels) { if ($groupOfLabel[$l] -eq $drop) { $groupOfLabel[$l] = $keep } }
4968:                 $changed = $true
4969:             }
4970:         }
4971:     }
4972:     $groups = New-Object System.Collections.Generic.List[object]
4973:     $indexOf = @{}
4974:     $groupOf = @{}
4975:     foreach ($m in @($Runners | Where-Object { $_ })) {
4976:         $label = [string]$m.Entry.Provider
4977:         $gid = $groupOfLabel[$label]
4978:         if (-not $indexOf.ContainsKey($gid)) {
4979:             $indexOf[$gid] = $groups.Count
4980:             $groups.Add([pscustomobject]@{ Labels = (New-Object System.Collections.Generic.List[string]); Limit = 0; Positions = (New-Object System.Collections.Generic.List[int]) })
4981:         }
4982:         $g = $groups[$indexOf[$gid]]
4983:         if (-not $g.Labels.Contains($label)) { $g.Labels.Add($label) }
4984:         $g.Positions.Add([int]$m.Entry.Position)
4985:         $groupOf[[int]$m.Entry.Position] = $indexOf[$gid]
4986:     }
4987:     $effective = 0
4988:     $limits = [ordered]@{}
4989:     $out = New-Object System.Collections.Generic.List[object]
4990:     foreach ($g in $groups) {
4991:         $limit = 0
4992:         foreach ($l in $g.Labels) {
4993:             $v = 1
4994:             if ($null -ne $Parallel -and $Parallel.ContainsKey($l)) { $v = [int]$Parallel[$l] }
4995:             if ($limit -eq 0 -or $v -lt $limit) { $limit = $v }
4996:         }
4997:         $effective += [Math]::Min($limit, $g.Positions.Count)
4998:         $out.Add([pscustomobject]@{ Labels = [string[]]$g.Labels.ToArray(); Limit = $limit; Positions = [int[]]$g.Positions.ToArray() })
4999:     }
5000:     foreach ($l in $labels) { $limits[$l] = $out[$indexOf[$groupOfLabel[$l]]].Limit }
5001:     if ($Cap -gt 0 -and $Cap -lt $effective) { $effective = $Cap }
5002:     $count = @($Runners | Where-Object { $_ }).Count
5003:     $text = if ($effective -ge $count) { 'at once' } elseif ($effective -le 1) { 'one after another' } else { "at most $effective at a time" }
5004:     return [pscustomobject]@{ Groups = [object[]]$out.ToArray(); GroupOf = $groupOf; Cap = $Cap; Effective = $effective; Text = $text; Limits = $limits }
5005: }
