4395: function ConvertTo-WhenOffset {
4396:     param($Value)
4397:     if ($Value -is [DateTimeOffset]) { return $Value }
4398:     if ($Value -is [datetime]) { return [DateTimeOffset]$Value }
4399:     $at = [DateTimeOffset]::MinValue
4400:     if ([DateTimeOffset]::TryParse([string]$Value, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$at)) { return $at }
4401:     return $null
4402: }
