4404: # Health of one ENDPOINT (provider_fingerprint - never the alias) from the ledgers of all
4405: # tasks. Entries recorded before 0.3.0 count as the built-in openai endpoint; entries with
4406: # an unresolved identity (empty fingerprint) are ignored. A failure's class comes from its
4407: # provider_failure, else (older entries) from its bridge_outcome. Newest wins: a later
4408: # successful run clears an earlier auth or quota failure ("later" by completion: finished_at,
4409: # else when + wall_seconds; ties by n). $UtcNow: the consult clock
4410: # (Get-ConsultClock -Peek), so a test can freeze time.
4411: #   Auth         the newest of {success, auth failure} is an auth failure <= 24 h old
4412: #   Quota        the newest of {success, quota failure} is a quota failure that still
4413: #                blocks: its RetryAfter lies in the future, or it has no RetryAfter and is
4414: #                <= 60 min old (a RetryAfter in the past clears it)
4415: #   QuotaKnown   [bool] Quota is set and names its reset time (RetryAfter)
4416: #   LastLimit    the newest quota failure <= 24 h old (informational)
4417: #   LastFailure  the newest failure of any class <= 24 h old (informational)
4418: #   RecentUsable the newest usable reply <= 60 min old (wave 18: an engine's sign-in is then
4419: #                evidenced without a network check - Get-EngineCredential)
4420: # Each record is $null or { Class; Code; Message; When; AgeMinutes (a `when` in the future
4421: # counts as now: 0); RetryAfter (DateTimeOffset or $null: provider_failure.retry_after, else
4422: # Get-RetryAfter -ReferenceOffset on the recorded message with the failure's `when` as
4423: # reference); RetryAfterIso ('' when none); RetryAfterBasis ('ledger' | 'message (reference
4424: # offset)' | ''); Until (RetryAfter, else When + 60 min) }.
4425: function Get-EndpointHealth {
4426:     param([object[]]$Consults, [string]$Fingerprint, [datetime]$UtcNow = [datetime]::UtcNow)
4427:     $h = [pscustomobject]@{ Auth = $null; Quota = $null; QuotaKnown = $false; LastLimit = $null; LastFailure = $null; RecentUsable = $null }
4428:     if (-not $Fingerprint) { return $h }
4429:     $records = New-Object System.Collections.Generic.List[object]
4430:     foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
4431:         $rev = Get-PropertyValue $c 'reviewer' $null
4432:         $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
4433:         if (-not $fp -or $fp -ne $Fingerprint) { continue }
4434:         $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
4435:         if (-not $outcome) { continue }
4436:         $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
4437:         if ($null -eq $at) { continue }
4438:         # A failure stamped in the future (clock skew, a mislabelled zone) counts as now:
4439:         # its age is clamped to 0, it is never skipped (F15-4).
4440:         $age = [Math]::Max(0, ($UtcNow - $at.UtcDateTime).TotalMinutes)
4441:         # "Newest" is by COMPLETION (D9, F03-3): a panel's members start together and finish in
4442:         # any order, so a member that started later may have succeeded before an earlier one hit
4443:         # its usage limit. finished_at (0.4.x wave 21), else when + wall_seconds (older entries),
4444:         # else when; ties by n (F02-5).
4445:         $order = ConvertTo-WhenOffset (Get-PropertyValue $c 'finished_at' '')
4446:         if ($null -eq $order) {
4447:             $order = $at
4448:             $ws = 0.0
4449:             if ([double]::TryParse([string](Get-PropertyValue $c 'wall_seconds' ''), [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$ws) -and $ws -gt 0) { $order = $at.AddSeconds($ws) }
4450:         }
4451:         $entryN = 0
4452:         [void][int]::TryParse([string](Get-PropertyValue $c 'n' ''), [ref]$entryN)
4453:         $rec = [pscustomobject]@{ At = $at; Order = $order; N = $entryN; Ok = ($outcome -eq 'usable reply'); Class = ''; Code = ''; Message = ''; When = $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); AgeMinutes = [int][Math]::Max(0, [Math]::Floor($age)); Age = $age; RetryAfter = $null; RetryAfterIso = ''; RetryAfterBasis = ''; Until = $at.AddMinutes(60) }
4454:         if (-not $rec.Ok) {
4455:             $reference = $at
4456:             $pf = Get-PropertyValue $c 'provider_failure' $null
4457:             if ($null -ne $pf) {
4458:                 $rec.Class = [string](Get-PropertyValue $pf 'class' 'unknown')
4459:                 # An entry recorded as auth whose message says usage limit / quota / rate limit
4460:                 # counts as quota (Get-ProviderFailureClass's rule, applied when the ledger is
4461:                 # READ): a 401/403 with a usage-limit text recorded before that rule existed
4462:                 # (Kimi Code's 5-hour limit) stops refusing the endpoint for 24 h as an auth
4463:                 # failure - without anyone editing the ledger.
4464:                 if ($rec.Class -eq 'auth' -and ([string](Get-PropertyValue $pf 'message' '')) -match $script:QuotaTextPattern) { $rec.Class = 'quota' }
4465:                 $rec.Code = [string](Get-PropertyValue $pf 'code' '')
4466:                 $rec.Message = [string](Get-PropertyValue $pf 'message' '')
4467:                 $pfWhen = ConvertTo-WhenOffset (Get-PropertyValue $pf 'when' '')
4468:                 if ($null -ne $pfWhen) { $reference = $pfWhen }
4469:                 $recorded = Get-PropertyValue $pf 'retry_after' $null
4470:                 if ($null -ne $recorded -and "$recorded") { $rec.RetryAfter = ConvertTo-WhenOffset $recorded }
4471:             } else {
4472:                 # older entry: classify its bridge_outcome, lifting an SSE/JSON error payload
4473:                 $parsedOutcome = ConvertFrom-ProviderErrorText -Text $outcome
4474:                 $rec.Class = Get-ProviderFailureClass "$($parsedOutcome.Code) $outcome"
4475:                 $rec.Code = $parsedOutcome.Code
4476:                 $rec.Message = $parsedOutcome.Message
4477:             }
4478:             # an entry recorded without retry_after: read the reset time from its message now
4479:             if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'ledger' }
4480:             else {
4481:                 $rec.RetryAfter = Get-RetryAfter -Message $rec.Message -Reference $reference -ReferenceOffset
4482:                 if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'message (reference offset)' }
4483:             }
4484:             if ($null -ne $rec.RetryAfter) {
4485:                 $rec.RetryAfterIso = Format-OffsetIso $rec.RetryAfter
4486:                 $rec.Until = $rec.RetryAfter
4487:             }
4488:             if ($rec.Message.Length -gt 100) { $rec.Message = $rec.Message.Substring(0, 100) }
4489:         }
4490:         $records.Add($rec)
4491:     }
4492:     $sorted = @($records | Sort-Object -Property @{ Expression = { $_.Order }; Descending = $true }, @{ Expression = { $_.N }; Descending = $true })
4493:     $auth = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'auth' }) | Select-Object -First 1
4494:     if ($auth -and -not $auth.Ok -and $auth.AgeMinutes -le 24 * 60) { $h.Auth = $auth }
4495:     $quota = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'quota' }) | Select-Object -First 1
4496:     if ($quota -and -not $quota.Ok) {
4497:         if ($null -ne $quota.RetryAfter) {
4498:             if ($quota.RetryAfter.UtcDateTime -gt $UtcNow) { $h.Quota = $quota }
4499:         } elseif ($quota.AgeMinutes -le 60) {
4500:             $h.Quota = $quota
4501:         }
4502:     }
4503:     $h.QuotaKnown = [bool]($h.Quota -and $null -ne $h.Quota.RetryAfter)
4504:     $h.LastLimit = @($sorted | Where-Object { -not $_.Ok -and $_.Class -eq 'quota' -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4505:     $h.LastFailure = @($sorted | Where-Object { -not $_.Ok -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
4506:     $h.RecentUsable = @($sorted | Where-Object { $_.Ok -and $_.Age -le 60 }) | Select-Object -First 1
4507:     return $h
4508: }
